'''Handler for inline assembly functions.'''
import copy
import hashlib
import os
import time
from .lexer import tokenise
#Each function call or operation that otherwise needs differentation includes a call ID.
#Each call ID is generated by hashing the previous one, so they are always distinct.
callid = str(time.time())
def next_call():
    '''Generates a new call ID.'''
    global callid
    callid = hashlib.sha1(callid.encode('utf-8')).hexdigest()
    return callid
mneumonics = ['ADD', 'SUB', 'LDA', 'STA', 'STO', 'BRA', 'BRZ', 'BRP','INP', 'OUT', 'OTC', 'HLT', 'COB', 'DAT']
class InlineFunction:
    '''Class representing an inline assembly function.'''
    name = ''
    params = []
    code = []
    def __init__(self, fname, params, assembly):
        self.name = fname.data
        self.params = [x.data for x in params]
        self.code = list(assembly)
    def __repr__(self):
        output = f'InlineFunction {self.name}('
        for x in range(len(self.params)):
            output += self.params[x]
            if (x+1) != len(self.params):
                output += ', '
        output += ')'
        return output
    def call(self, params) -> str:
        '''Generates inline assembly to call the function.'''
        next_call()
        if len(params) != len(self.params):
            raise ValueError(f'{self} takes {len(self.params)} arguments but {len(params)} were given. ({params})')
        code2 = copy.deepcopy(self.code)
        for x in code2:
            if x.data in self.params:
                x.data = params[self.params.index(x.data)]
        asm = ''

        pos = -1
        for x in code2:
            pos += 1
            if x.data == ';':
                asm = asm + '\n'
            else:
                #Convert integer literals to integer variables:
                if x.ttype == 'int' and code2[pos-1].data != 'DAT':
                    x.data = '__int.' + x.data
                    x.ttype = 'sym'
                #Convert character literals to integer variables:
                if x.ttype == 'chr' and code2[pos-1].data != 'DAT':
                    x.data = '__int.' + str(ord(x.data))
                    x.ttype = 'sym'
                if x.ttype == 'sym' and x.data not in params and x.data not in mneumonics and not x.data.startswith('__'):
                    x.data = '__' + self.name + '_' + callid + '.' + x.data
                asm += x.data + ' '
        return asm
    def __call__(self, params) -> str:
        return self.call(params)
def parse_lib(code) -> dict:
    '''Parses inline assembly into a dictionary of functions.'''
    tokens = tokenise(code)
    position = 0
    functions = {}
    while position < len(tokens):
        symbol = tokens[position]
        if symbol.data == 'asm':
            fname, params, assembly = tokens[position+1:position+4]
            functions[fname.data] = InlineFunction(fname, params, assembly)
            position += 4
            continue
        position += 1
    return functions
inline_functions = {}
libdir = os.path.dirname(os.path.dirname(__file__)) + '/lib'
libraries =  [x for x in os.listdir(libdir) if x.endswith('.lma')]
for x in libraries:
    with open(libdir + '/' + x, 'r', encoding='utf-8') as f:
        data = f.read()
    funcs = parse_lib(data)
    for x in funcs:
        inline_functions[x] = funcs[x]
